/// Regenerated by `cargo run -p zapret-hub --bin export-bindings` and by every debug start.
const BINDINGS_PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../frontend/src/lib/ipc/bindings.ts"
);

fn specta_builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new()
        .events(collect_events![
            dto::TestProgress,
            dto::TestsFinished,
            dto::StateChanged,
            dto::NoticesChanged,
            dto::DownloadProgress
        ])
        .commands(collect_commands![
            commands::app_version,
            commands::get_settings,
            commands::save_settings,
            commands::get_overview,
            commands::check_proxy,
            commands::wizard_candidates,
            commands::detect_folders,
            commands::pick_folder,
            commands::open_url,
            commands::open_folder,
            commands::list_strategies,
            commands::get_strategy,
            commands::apply_strategy,
            commands::apply_best,
            commands::restart_zapret,
            commands::zapret2_info,
            commands::check_zapret2_folder,
            commands::validate_zapret2,
            commands::save_zapret2,
            commands::delete_zapret2,
            commands::zapret2_profiles,
            commands::zapret2_circular,
            commands::zapret2_merge,
            commands::start_tests,
            commands::cancel_tests,
            commands::default_download_parent,
            commands::download_engine,
            commands::cancel_download,
            commands::test_live,
            commands::list_runs,
            commands::get_run,
            commands::run_report,
            commands::clear_discord_cache,
            commands::remove_service,
            commands::stop_service,
            commands::start_service,
            commands::restart_service,
            commands::nft_rules,
            commands::service_logs,
            commands::flush_dns,
            commands::tg_ws_status,
            commands::install_tg_ws,
            commands::set_tg_ws_enabled,
            commands::save_tg_ws_config,
            commands::open_tg_proxy,
            commands::get_exclusions,
            commands::save_exclusions,
            commands::quick_check,
            commands::take_notices,
            commands::set_router_enabled,
            commands::router_status,
            commands::list_routes,
            commands::get_route,
            commands::save_route,
            commands::set_route_enabled,
            commands::delete_route,
            commands::add_route_preset,
            commands::route_flows,
            commands::doctor,
            commands::probe,
            commands::fix_doctor_issue,
            commands::fix_all_doctor_issues,
            commands::validate_route,
            commands::import_route_lines
        ])
}

pub fn export_bindings() -> anyhow::Result<()> {
    specta_builder()
        .export(Typescript::default(), BINDINGS_PATH)
        .map_err(|err| anyhow::anyhow!("failed to export IPC bindings: {err}"))
}

/// What `main` does with an error from `run`.
pub fn report(err: &anyhow::Error) {
    fatal(&format!("{}\n\n{err:#}", texts::FAILED_TO_START));
}

/// There is no window to show the error in: log, console and a desktop notification.
fn fatal(text: &str) {
    log::error!("{text}");
    eprintln!("{text}");
    let _ = std::process::Command::new("notify-send")
        .arg("-a")
        .arg(texts::APP)
        .arg(texts::FAILED_TO_START)
        .arg(text)
        .spawn();
}

pub fn run() -> anyhow::Result<()> {
    let paths = Paths::current()?;
    journal::init(paths.logs());
    log::info!(
        "Zapret Hub {} started from {}",
        env!("CARGO_PKG_VERSION"),
        paths.exe_dir.display()
    );
    let (mut settings, damaged) = settings::load_or_default(&paths.settings());
    // The `tg://proxy` link must survive restarts: a secret absent from the file is generated
    // once here. Best effort: the app still starts, the field stays empty on disk.
    if let Err(err) = crate::tgws::ensure_secret(&mut settings) {
        log::warn!("cannot generate the tg-ws secret: {err:#}");
    } else if let Err(err) = settings::save(&paths.settings(), &settings) {
        log::warn!("cannot save the generated tg-ws secret: {err:#}");
    }
    let state = AppState::new(paths, settings);
    state.migrate_strategies();
    if let Some(text) = damaged {
        state.push_notice(Notice {
            level: NoticeLevel::Error,
            title: texts::SETTINGS_RESET.to_owned(),
            text,
        });
    }
    // The Task Scheduler entry passes it (autostart.rs).
    let autostarted = std::env::args().any(|arg| arg == "--autostart");
    let builder = specta_builder();
    #[cfg(debug_assertions)]
    if let Err(err) = export_bindings() {
        log::warn!("{err:#}");
    }
    tauri::Builder::default()
        // First: a second copy hands over to this one before anything else starts.
        .plugin(tauri_plugin_single_instance::init(|app, _args, _cwd| {
            window::show(app)
        }))
        .plugin(tauri_plugin_dialog::init())
        .manage(state)
        // The cross hides the window instead of destroying it: the last window gone makes the GTK
        // main loop quit and kills the tray. Only the tray's «Выход» may end the app.
        .on_window_event(|window, event| {
            if let tauri::WindowEvent::CloseRequested { api, .. } = event {
                api.prevent_close();
                let _ = window.hide();
            }
        })
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            notify::register();
            tray::create(app.handle())?;
            // The router's state or its proxy's kind of state changed; latency alone does not call.
            let handle = app.handle().clone();
            app.state::<AppState>()
                .router
                .on_change(move || actions::changed(&handle));
            let settings = app.state::<AppState>().settings();
            // A logon start stays in the tray once the wizard is done (spec 9.2, 9.3).
            if !(autostarted && settings.start_minimized && settings.wizard_done) {
                window::show(app.handle());
            }
            jobs::start(app.handle());
            cli::start(app.handle());
            Ok(())
        })
        .build(tauri::generate_context!())?
        .run(|_app, event| {
            // The close button leaves the app in the tray; only «Выход» ends it (spec 4.2).
            if let tauri::RunEvent::ExitRequested {
                code: None, api, ..
            } = event
            {
                api.prevent_exit();
            }
        });
    Ok(())
}
